7	// Per-book-update microstructure signals: Order Flow Imbalance (OFI) and
8	// microprice (plan: .claude/plans/microstructure-signals.md, steps 2-3).
9	//
10	// Design note: this wraps OrderBookFlat rather than adding fields to it, so
11	// the book keeps a single responsibility and its latency benchmarks stay
12	// comparable with docs/perf/01-flat-book.md. The engine applies each parsed
13	// message to the book, snapshots top-of-book, and emits one MicroEvent per
14	// update.
15	//
16	// OFI follows the best-level definition of Cont, Kukanov & Stoikov (2014),
17	// "The Price Impact of Order Book Events": with best bid (P_b, q_b) and best
18	// ask (P_a, q_a), the event-n contribution is
19	//
20	//   e_n =  1{P_b_n >= P_b_{n-1}} * q_b_n  -  1{P_b_n <= P_b_{n-1}} * q_b_{n-1}
21	//        - 1{P_a_n <= P_a_{n-1}} * q_a_n  +  1{P_a_n >= P_a_{n-1}} * q_a_{n-1}
22	//
23	// Positive e_n = net buying pressure (bid depth added, ask depth consumed).
24	//
25	// Microprice is the depth-weighted mid: with imbalance I = q_b / (q_b + q_a),
26	//   microprice = I * P_a + (1 - I) * P_b
27	// It leans toward the side with LESS depth's price being hit next — a better
28	// short-horizon fair-value estimate than the plain mid.
29	
30	namespace itch {
31	
32	struct MicroEvent {
33	    uint64_t timestamp_ns;   // ITCH ns-since-midnight of the triggering message
34	    double   ofi;            // per-event OFI increment e_n, in shares (signed)
35	    double   microprice;     // depth-weighted mid, in dollars
36	    double   best_bid;       // dollars
37	    double   best_ask;       // dollars
38	    uint32_t bid_size;       // shares at best bid
39	    uint32_t ask_size;       // shares at best ask
40	};
41	
42	class MicrostructureEngine {
43	public:
44	    // Same construction contract as OrderBookFlat: the instrument's expected
45	    // fixed-point tick range must be declared up front.
46	    MicrostructureEngine(uint32_t min_price_raw, uint32_t max_price_raw,
47	                         uint32_t tick_size = 1)
48	        : book_(min_price_raw, max_price_raw, tick_size) {}
