TEST(Integration, AddExecuteDeleteViaParser) {
    // Build a buffer: add bid, add ask, execute half of bid, delete rest.
    uint32_t bid_price = 1000000;  // 100.0000
    uint32_t ask_price = 1010000;  // 101.0000

    auto buf = cat({
        make_add(1, 'B', 200, bid_price),
        make_add(2, 'S', 300, ask_price),
        make_execute(1, 100),
        make_delete(1),
    });

    itch::OrderBook book;
    itch::MessageVisitor visitor;
    visitor.on_add     = [&](const itch::AddOrder& m)     { book.add(m.order_ref, m.side, m.price, m.shares); };
    visitor.on_execute = [&](const itch::ExecuteOrder& m)  { book.execute(m.order_ref, m.executed_shares); };
    visitor.on_delete  = [&](const itch::DeleteOrder& m)   { book.del(m.order_ref); };
    visitor.on_replace = [&](const itch::ReplaceOrder& m)  { book.replace(m.old_order_ref, m.new_order_ref, m.shares, m.price); };

    itch::ParseStats stats = itch::parse_buffer(buf.data(), buf.size(), visitor);
    EXPECT_EQ(stats.add_count,     2u);
    EXPECT_EQ(stats.execute_count, 1u);
    EXPECT_EQ(stats.delete_count,  1u);
    EXPECT_EQ(stats.error_count,   0u);

    // After execute(100) + delete, the bid side should be empty.
    // Ask side should still have 300 shares at ask_price.
    auto tob = book.top_of_book();
    EXPECT_FALSE(tob.best_bid.has_value());
    ASSERT_TRUE(tob.best_ask.has_value());
    EXPECT_EQ(tob.best_ask->price_raw, ask_price);
    EXPECT_EQ(tob.best_ask->shares,    300u);
}

// ─── Flat-array book correctness tests ──────────────────────────────────────

#include "../itch/order_book_flat.hpp"

TEST(OrderBookFlat, AddThenTopOfBook) {
    itch::OrderBookFlat book(900000, 1100000);
    book.add(1, 'B', 1000000, 100);
    book.add(2, 'S', 1010000, 200);

    auto tob = book.top_of_book();
    ASSERT_TRUE(tob.best_bid.has_value());
    ASSERT_TRUE(tob.best_ask.has_value());
    EXPECT_EQ(tob.best_bid->price_raw, 1000000u);
    EXPECT_EQ(tob.best_ask->price_raw, 1010000u);
}

TEST(OrderBookFlat, AddExecuteDeleteSequence) {
    itch::OrderBookFlat book(900000, 1100000);
    book.add(10, 'B', 1000000, 100);

    uint32_t filled = book.execute(10, 60);
    EXPECT_EQ(filled, 60u);

    auto tob = book.top_of_book();
    ASSERT_TRUE(tob.best_bid.has_value());
    EXPECT_EQ(tob.best_bid->shares, 40u);

    book.del(10);
    tob = book.top_of_book();
    EXPECT_FALSE(tob.best_bid.has_value());
}

TEST(OrderBookFlat, OutOfRangePriceIncreasesErrorCount) {
    itch::OrderBookFlat book(1000000, 1010000);
    book.add(1, 'B', 500000, 100);  // below min_price
    EXPECT_EQ(book.error_count(), 1u);
}

TEST(OrderBookFlat, MatchesHashMapBookOnSameSequence) {
    // Both books process the same Add→Execute→Delete sequence and
    // must arrive at the same top-of-book.
    auto buf = cat({
        make_add(1, 'B', 100, 1000000),
        make_add(2, 'S', 50,  1010000),
        make_execute(1, 50),
    });

    itch::OrderBook     map_book;
    itch::OrderBookFlat flat_book(990000, 1020000);

    auto apply = [&](auto& book) {
        itch::MessageVisitor v;
        v.on_add     = [&](const itch::AddOrder& m)     { book.add(m.order_ref, m.side, m.price, m.shares); };
        v.on_execute = [&](const itch::ExecuteOrder& m)  { book.execute(m.order_ref, m.executed_shares); };
        v.on_delete  = [&](const itch::DeleteOrder& m)   { book.del(m.order_ref); };
        v.on_replace = [&](const itch::ReplaceOrder& m)  { book.replace(m.old_order_ref, m.new_order_ref, m.shares, m.price); };
        return itch::parse_buffer(buf.data(), buf.size(), v);
    };

    apply(map_book);
    apply(flat_book);

    auto tob_map  = map_book.top_of_book();
    auto tob_flat = flat_book.top_of_book();

    ASSERT_EQ(tob_map.best_bid.has_value(), tob_flat.best_bid.has_value());

