123	// ─── MicrostructureEngine: hand-computed OFI / microprice sequences ─────────
124	//
125	// All scenarios build the same starting book:
126	//   bid: order 1, 100 sh @ $100.00 (raw 1000000)
127	//   ask: order 2, 200 sh @ $100.05 (raw 1000500)
128	
129	namespace {
130	
131	constexpr uint32_t MIN_P = 990000, MAX_P = 1020000;
132	constexpr uint32_t BID_P = 1000000, ASK_P = 1000500;
133	
134	itch::MicrostructureEngine make_seeded_engine() {
135	    itch::MicrostructureEngine eng(MIN_P, MAX_P);
136	    eng.on_add({1000, 1, 'B', 100, BID_P});
137	    eng.on_add({2000, 2, 'S', 200, ASK_P});
