143	TEST(MicroEngine, FirstTwoSidedEventIsBaseline) {
144	    auto eng = make_seeded_engine();
145	
146	    // First add is one-sided (no ask yet) -> skipped; second add is the
147	    // first computable event.
148	    ASSERT_EQ(eng.events().size(), 1u);
149	    EXPECT_EQ(eng.skipped_one_sided(), 1u);
150	
151	    const auto& ev = eng.events()[0];
152	    EXPECT_EQ(ev.timestamp_ns, 2000u);
153	    EXPECT_DOUBLE_EQ(ev.ofi, 0.0);           // no previous state: baseline
154	    EXPECT_NEAR(ev.best_bid, 100.00, 1e-9);
155	    EXPECT_NEAR(ev.best_ask, 100.05, 1e-9);
156	    EXPECT_EQ(ev.bid_size, 100u);
157	    EXPECT_EQ(ev.ask_size, 200u);
158	    // microprice = (q_b*P_a + q_a*P_b) / (q_b+q_a)
159	    //            = (100*100.05 + 200*100.00) / 300 = 30005/300 = 100.01666...
160	    EXPECT_NEAR(ev.microprice, 100.0 + 0.05 / 3.0, 1e-9);
161	}
