163	TEST(MicroEngine, AddingBidDepthAtSamePriceIsPositiveOFI) {
164	    auto eng = make_seeded_engine();
165	    eng.on_add({3000, 3, 'B', 50, BID_P});   // bid level 100 -> 150 sh
166	
167	    ASSERT_EQ(eng.events().size(), 2u);
168	    const auto& ev = eng.events()[1];
169	    // Same best-bid price: e = q_b_new - q_b_old = 150 - 100 = +50.
170	    // Ask unchanged: -q_a_new + q_a_old = 0.
171	    EXPECT_DOUBLE_EQ(ev.ofi, 50.0);
172	    EXPECT_EQ(ev.bid_size, 150u);
173	}
