176	    auto eng = make_seeded_engine();
177	    eng.on_execute({3000, 2, 40});           // ask level 200 -> 160 sh
178	
179	    ASSERT_EQ(eng.events().size(), 2u);
180	    const auto& ev = eng.events()[1];
181	    // Buy market order consumed ask depth: e = -160 + 200 = +40.
182	    EXPECT_DOUBLE_EQ(ev.ofi, 40.0);
183	    EXPECT_EQ(ev.ask_size, 160u);
184	}
